import type { Metadata } from "next";
import { notFound } from "next/navigation";
import Link from "next/link";
import type { Post, Comment } from "../types";

interface BlogPostPageProps {
  params: Promise<{
    id: string;
  }>;
}

export const revalidate = 300;

async function getPost(id: string): Promise<Post | null> {
  try {
    const res = await fetch(
      `https://jsonplaceholder.typicode.com/posts/${id}`,
      {
        next: { revalidate: 300 },
      }
    );
    if (!res.ok) {
      return null;
    }
    return res.json();
  } catch {
    return null;
  }
}

async function getComments(id: string): Promise<Comment[]> {
  try {
    const res = await fetch(
      `https://jsonplaceholder.typicode.com/posts/${id}/comments`,
      {
        next: { revalidate: 300 },
      }
    );
    if (!res.ok) {
      return [];
    }
    return res.json();
  } catch {
    return [];
  }
}

export async function generateMetadata({
  params,
}: BlogPostPageProps): Promise<Metadata> {
  const { id } = await params;
  const post = await getPost(id);

  if (!post) {
    return {
      title: "Post Not Found",
    };
  }

  return {
    title: `${post.title} - My Blog`,
    description: post.body.substring(0, 160),
    openGraph: {
      title: post.title,
      description: post.body.substring(0, 160),
    },
  };
}

export default async function BlogPostPage({ params }: BlogPostPageProps) {
  const { id } = await params;
  const [post, comments] = await Promise.all([getPost(id), getComments(id)]);

  if (!post) {
    notFound();
  }

  return (
    <article>
      <Link href="/blog">
        <button>← Back</button>
      </Link>

      <h1>{post.title}</h1>
      <p>{post.body}</p>

      <h2>Comments ({comments.length})</h2>
      <div className="comments">
        {comments.map((comment: Comment) => (
          <div key={comment.id} className="comment">
            <h3>{comment.name}</h3>
            <p>{comment.body}</p>
            <small>By: {comment.email}</small>
          </div>
        ))}
      </div>
    </article>
  );
}

import type { ApiPost } from "../../types";

export const dynamic = "force-dynamic";

export async function GET(): Promise<Response> {
  const posts: ApiPost[] = [
    { id: 1, title: "First Post", content: "This is the first post" },
    { id: 2, title: "Second Post", content: "This is the second post" },
  ];

  return Response.json(posts);
}

export async function POST(request: Request): Promise<Response> {
  try {
    const body = (await request.json()) as { title?: string; content?: string };
    const { title, content } = body;

    if (!title || !content) {
      return Response.json(
        { error: "Title and content are required" },
        { status: 400 }
      );
    }

    const newPost: ApiPost = {
      id: Date.now(),
      title,
      content,
      createdAt: new Date().toISOString(),
    };

    return Response.json(newPost, { status: 201 });
  } catch {
    return Response.json({ error: "Invalid request body" }, { status: 400 });
  }
}

import { NextRequest } from "next/server";
import type { ApiPost } from "../../../types";

interface RouteParams {
  params: Promise<{
    id: string;
  }>;
}

export async function GET(
  _request: NextRequest,
  { params }: RouteParams
): Promise<Response> {
  const { id } = await params;
  const postId = parseInt(id, 10);

  const post: ApiPost = {
    id: postId,
    title: `Post ${id}`,
    content: `This is the content for post ${id}`,
    createdAt: new Date().toISOString(),
  };

  return Response.json(post);
}

export async function PUT(
  request: NextRequest,
  { params }: RouteParams
): Promise<Response> {
  const { id } = await params;
  const postId = parseInt(id, 10);

  try {
    const body = (await request.json()) as {
      title?: string;
      content?: string;
    };
    const { title, content } = body;

    const updatedPost: ApiPost = {
      id: postId,
      title: title || `Post ${id}`,
      content: content || `Updated content for post ${id}`,
      updatedAt: new Date().toISOString(),
    };

    return Response.json(updatedPost);
  } catch {
    return Response.json({ error: "Invalid request body" }, { status: 400 });
  }
}

export async function DELETE(
  _request: NextRequest,
  { params }: RouteParams
): Promise<Response> {
  const { id } = await params;

  return Response.json({ message: `Post ${id} deleted successfully` });
}

